import io,os,sys
p='v12/QUICKSTART.md'
if not os.path.isfile(p): sys.exit('no '+p)
t=io.open(p,encoding='utf-8').read()
need=['## Supported commands','## Execution is not acceptance','## Reading a failed attempt','## Cancelling or holding safely']
miss=[h for h in need if h not in t]
if miss: sys.exit('missing sections: '+', '.join(miss))
if len(t)<1200: sys.exit('quickstart is shorter than its own contract')
bad=[w for w in ['TODO','TBD','FIXME'] if w in t]
if bad: sys.exit('unresolved markers: '+', '.join(bad))
print('quickstart structure ok: %d bytes, %d sections'%(len(t),len(need)))
